"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read().splitlines()
    except FileNotFoundError:
        raise ConfigError("included file not found: {}".format(path))
    except OSError as exc:
        raise ConfigError("cannot read {}: {}".format(path, exc))


def _expand(path, stack):
    real = os.path.realpath(path)
    if real in stack:
        chain = " -> ".join(stack + [real])
        raise ConfigError("include cycle detected: {}".format(chain))
    lines = _read_lines(path)
    base_dir = os.path.dirname(os.path.abspath(path))
    stack = stack + [real]
    expanded = []
    for lineno, raw in enumerate(lines, start=1):
        parts = raw.split(None, 1)
        if parts and parts[0] == INCLUDE_DIRECTIVE:
            target = parts[1].strip() if len(parts) > 1 else ""
            if not target:
                raise ConfigError(
                    "{}:{}: @include requires a path".format(path, lineno)
                )
            target = os.path.join(base_dir, os.path.expanduser(target))
            expanded.extend(_expand(target, stack))
        else:
            expanded.append(raw)
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    with open(path, "r", encoding="utf-8") as fh:
        fh.read(0)
    return parse_lines(_expand(path, []))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
